func findAnagrams(s string, p string) []int {
    if len(s) < len(p) {
        return nil
    }
    var sCount, pCount [26]int
    for i := 0; i < len(p); i++ {
        pCount[p[i]-'a']++
        sCount[s[i]-'a']++
    }
    var res []int
    if sCount == pCount {
        res = append(res, 0)
    }
    for i := len(p); i < len(s); i++ {
        sCount[s[i]-'a']++
        sCount[s[i-len(p)]-'a']--
        if sCount == pCount { // Go 数组可直接 == 比较
            res = append(res, i-len(p)+1)
        }
    }
    return res
}
